import { canvasScene, arrow } from "./core/canvas.js";
import { profile } from "../data/profile.js";
let instance, cleanup;
const resonance = [5.35, 6.15, 6.85],
  widths = [0.8, 0.88, 0.7];
const ms = (f, m) => 1 / Math.sqrt(1 + ((f - resonance[m]) / widths[m]) ** 2);
export function init(container, options = {}) {
  destroy();
  let mode = 0,
    geometry,
    drawAge = 0;
  const labels = profile.diagrams.cma;
  instance = canvasScene(
    container,
    ({ ctx, w, h, t, dt, still, colors: c }) => {
      drawAge += dt;
      const drawProgress = still ? 1 : Math.min(1, drawAge / 1.4);
      const mobile = w < 600,
        plot = {
          x: 42,
          y: 35,
          w: mobile ? w - 62 : w * 0.56 - 50,
          h: mobile ? h * 0.4 : h - 90,
        },
        current = {
          x: mobile ? w * 0.5 : w * 0.8,
          y: mobile ? h * 0.77 : h * 0.53,
          r: mobile ? 70 : Math.min(105, w * 0.15),
        };
      geometry = plot;
      const px = (f) => plot.x + ((f - 4) / 4) * plot.w,
        py = (value) => plot.y + (1 - value) * plot.h;
      const palette = [c.cyan, c.amber, c.accent];
      ctx.font = '10px "JetBrains Mono", monospace';
      ctx.fillStyle = c.muted;
      ctx.fillText(labels.plot, plot.x, 17);
      ctx.save();
      ctx.beginPath();
      ctx.rect(plot.x, plot.y, plot.w, plot.h);
      ctx.clip();
      for (let m = 0; m < 3; m++) {
        ctx.globalAlpha = 0.04;
        ctx.fillStyle = palette[m];
        ctx.fillRect(
          px(resonance[m] - widths[m]),
          plot.y,
          (plot.w * widths[m]) / 2,
          plot.h * 0.293,
        );
      }
      ctx.restore();
      ctx.globalAlpha = 1;
      for (let k = 0; k <= 4; k++) {
        ctx.strokeStyle = c.line;
        ctx.lineWidth = 0.6;
        ctx.beginPath();
        ctx.moveTo(plot.x, py(k / 4));
        ctx.lineTo(plot.x + plot.w, py(k / 4));
        ctx.stroke();
        ctx.fillStyle = c.muted;
        ctx.fillText((k / 4).toFixed(2), 2, py(k / 4) + 4);
        ctx.fillText(String(4 + k), px(4 + k) - 3, plot.y + plot.h + 20);
      }
      ctx.setLineDash([4, 4]);
      ctx.strokeStyle = c.muted;
      ctx.beginPath();
      ctx.moveTo(plot.x, py(0.707));
      ctx.lineTo(plot.x + plot.w, py(0.707));
      ctx.stroke();
      ctx.setLineDash([]);
      ctx.fillStyle = c.muted;
      ctx.fillText(labels.significant, plot.x + plot.w - 88, py(0.707) - 7);
      ctx.fillText(
        labels.frequency,
        plot.x + plot.w * 0.33,
        plot.y + plot.h + 42,
      );
      for (let m = 0; m < 3; m++) {
        const selected = mode === m || (mode === 3 && m < 2);
        ctx.strokeStyle = palette[m];
        ctx.globalAlpha = selected ? 1 : 0.38;
        ctx.lineWidth = selected ? 2.7 : 1.2;
        ctx.beginPath();
        for (let i = 0; i <= 220 * drawProgress; i++) {
          const f = 4 + (4 * i) / 220;
          i ? ctx.lineTo(px(f), py(ms(f, m))) : ctx.moveTo(px(f), py(ms(f, m)));
        }
        ctx.stroke();
        ctx.globalAlpha = 1;
        ctx.fillStyle = palette[m];
        ctx.fillText(labels.modes[m], px(resonance[m]) - 8, py(1) - 10);
      }
      const { x, y, r } = current;
      ctx.fillStyle = c.surface;
      ctx.strokeStyle = c.line;
      ctx.lineWidth = 1;
      ctx.fillRect(x - r, y - r, r * 2, r * 2);
      ctx.strokeRect(x - r, y - r, r * 2, r * 2);
      for (let row = -2; row <= 2; row++)
        for (let col = -2; col <= 2; col++) {
          const xx = x + col * r * 0.35,
            yy = y + row * r * 0.35;
          ctx.strokeStyle = c.line;
          ctx.strokeRect(xx - r * 0.145, yy - r * 0.145, r * 0.29, r * 0.29);
          const ex = Math.cos((row * Math.PI) / 7),
            ey = Math.cos((col * Math.PI) / 7),
            scale = r * 0.25;
          let dx, dy;
          if (mode === 0) {
            dx = ex * Math.cos(t * 2);
            dy = 0;
          } else if (mode === 1) {
            dx = 0;
            dy = ey * Math.cos(t * 2);
          } else if (mode === 2) {
            dx = -row * 0.4 * Math.cos(t * 2);
            dy = col * 0.4 * Math.cos(t * 2);
          } else {
            dx = ex * Math.cos(t * 2);
            dy = ey * Math.sin(t * 2);
          }
          arrow(
            ctx,
            xx - dx * scale * 0.5,
            yy - dy * scale * 0.5,
            dx * scale,
            dy * scale,
            mode === 3 ? c.cyan : palette[mode],
            1.7,
          );
        }
      ctx.fillStyle = c.muted;
      ctx.fillText(labels.current, x - r, y - r - 20);
      ctx.fillText(
        mode === 3 ? labels.combine : labels.modes[mode],
        x - r,
        y + r + 24,
      );
    },
    options,
  );
  const buttons = [...container.parentElement.querySelectorAll("[data-mode]")];
  const select = (m) => {
    mode = m;
    buttons.forEach((b) =>
      b.setAttribute("aria-pressed", String(Number(b.dataset.mode) === m)),
    );
    instance.render();
  };
  const click = (e) => select(Number(e.currentTarget.dataset.mode));
  buttons.forEach((b) => b.addEventListener("click", click));
  const hover = (e) => {
    if (!geometry) return;
    const rect = instance.canvas.getBoundingClientRect(),
      x = e.clientX - rect.left,
      y = e.clientY - rect.top,
      p = geometry;
    if (x < p.x || x > p.x + p.w || y < p.y || y > p.y + p.h) return;
    const f = 4 + ((x - p.x) / p.w) * 4,
      value = 1 - (y - p.y) / p.h;
    const nearest = [0, 1, 2].sort(
      (a, b) => Math.abs(ms(f, a) - value) - Math.abs(ms(f, b) - value),
    )[0];
    if (Math.abs(ms(f, nearest) - value) < 0.07) select(nearest);
  };
  instance.canvas.addEventListener("pointermove", hover);
  instance.canvas.addEventListener("click", hover);
  cleanup = () => {
    buttons.forEach((b) => b.removeEventListener("click", click));
    instance.canvas.removeEventListener("pointermove", hover);
    instance.canvas.removeEventListener("click", hover);
  };
  return instance;
}
export function destroy() {
  cleanup?.();
  instance?.destroy();
  instance = null;
}
